"""Add original passkey and checkout engineering lessons to local drafts."""
import copy
import datetime
import html
import json
import re
import subprocess
import uuid
from pathlib import Path

root = Path(__file__).resolve().parents[1]
fixture = root / 'src/data/fixtures.json'
entries = json.loads(fixture.read_text())
by_path = {entry['path']: entry for entry in entries}
stamp = datetime.datetime.now(datetime.UTC).isoformat()

def p(value):
    return '<p>' + html.escape(value) + '</p>'

def link(path):
    title = by_path[path]['title'] if path in by_path else next((item['title'] for item in lessons if item['path'] == path), None)
    assert title is not None, path
    return '<a href="/' + html.escape(path, quote=True) + '">' + html.escape(title) + '</a>'

hubs = [
    dict(path='web-tech/passkeys-and-account-assurance', title='Passkeys and Account Assurance', summary='Register and verify public-key credentials while preserving account recovery and session boundaries.', overview='A passkey is an account credential whose private key stays with an authenticator while the server stores a public key. Registration and sign-in each require a fresh server challenge, origin and relying-party scope checks, and a verified response before a session is created. The browser UI may be smooth, but server mistakes can still bind a credential to the wrong account or accept a replay. This track follows a case-review product with shared devices, synced passkeys, and account recovery needs. It treats authenticator choice and credential removal as product states, not as hidden browser details.', bridges=['web-tech/identity-and-application-security','web-tech/authorization-and-tenant-boundaries']),
    dict(path='web-tech/checkout-and-payment-state', title='Checkout and Payment State', summary='Keep amounts server-owned and reconcile provider events before fulfilling an order.', overview='Checkout spans a cart, a server-priced order, a provider-owned payment flow, browser return pages, and asynchronous provider events. The browser is a user interface, not the authority for final amount or payment completion. This track uses a fictional equipment-store order with integer money values and a hosted payment page. It focuses on duplicate submissions, uncertain responses, verified callbacks, order fulfillment, and reversal states. Actual provider methods, currencies, and compliance scope require a chosen integration and current review.', bridges=['web-tech/backend-api-systems','web-tech/signed-webhook-delivery-and-replay']),
]

lessons = [
    dict(hub=0, path='web-tech/passkey-registration-challenge-and-credential-binding', title='Passkey Registration Challenge and Credential Binding', summary='Issue a fresh server challenge and bind the returned public key to the intended signed-in account.',
    definition='Passkey registration creates a public-key credential for a relying party. The browser asks an authenticator to create a key pair, while the application server later stores the credential identifier and public key for one account. A successful browser create call does not by itself authorize account attachment. The server must issue an unpredictable, short-lived challenge, remember its purpose and account context, and verify the returned client data and authenticator data before persisting anything. Registration is a privileged account mutation; a stolen active session or weak recovery flow can still attach an attacker-controlled credential.',
    case='Reviewer 29 is signed into organization 6 and chooses Add a passkey from account settings. The server creates challenge C-47 scoped to that account, registration action, expected relying-party ID, and expiration. The browser opens the authenticator prompt. When the response returns, the server checks that C-47 is current and unused, verifies the client origin and relying-party scope, checks required flags and credential data using a maintained verification implementation, then stores the public key under reviewer 29. A second request that attempts to reuse C-47 is rejected. An account switch during the prompt cannot bind the result to reviewer 62.',
    implementation='Generate challenges with a cryptographically secure source on the server and store an opaque challenge record bound to the current authenticated actor and action. Do not trust an account ID or display name echoed by the browser to choose the owner. Validate expected origin, relying-party ID hash, challenge, credential type, and user-presence or verification policy through a maintained WebAuthn server library. Attestation policy depends on the product and should not be confused with proof that the user owns an account. Consume the challenge once, reject duplicate credential IDs where required, and persist credential metadata with a minimal device label the person can manage later.',
    cost='Creating a challenge is O(1) storage and random generation; verification includes cryptographic work and parsing bounded response data. Each credential adds a public key record and account-management surface. An account with several synced or device-bound credentials needs duplicate and removal rules, and a registration prompt can remain pending while the page changes. Measure challenge expiry and replay rejection, failed verification reasons without logging sensitive raw assertions, and how often users can finish registration. Correctness matters more than shaving a small verification cost.',
    failure='A server accepts any registration response as long as a signed-in session exists. An attacker replays an old response or switches accounts during a delayed prompt and gets a credential attached to the wrong profile. Bind and consume the challenge under the original actor. Another implementation accepts a passkey created for a lookalike origin because it checks only the credential identifier. Verify origin and relying-party scope. Test expired and reused challenges, a canceled prompt, duplicate credential IDs, an account switch, and a session revoked before final registration.',
    drill='Issue a registration challenge for reviewer 29, then submit a valid response through a real verification library. Replay the same response, alter the origin, bind it to reviewer 62, and let the challenge expire. Confirm each invalid path leaves no credential record. Interrupt the browser prompt and check that no pending challenge grants access. Add two valid passkeys with distinct labels and inspect the account settings list before testing one-credential removal.',
    decision='Treat registration as a server-authorized account mutation whose challenge, origin, and credential data are verified before storage.',
    code='function registrationContextMatches(pending, current) {\n  return pending.actorId === current.actorId && pending.action === "register-passkey" && !pending.used && current.now < pending.expiresAt;\n}\nconsole.log(registrationContextMatches({ actorId: 29, action: "register-passkey", used: false, expiresAt: 80 }, { actorId: 62, now: 47 }));\n// Output: false',
    checks=['A returned credential binds only to the challenge owner.','Expired or reused challenges cannot create credentials.','Origin and relying-party scope are verified before storage.'], mistakes=['Treating browser create success as server verification.','Choosing the account from client-supplied fields.','Reusing one challenge for registration and sign-in.'], related=['web-tech/password-verification-and-login-budgets','web-tech/account-recovery-and-session-revocation','web-tech/session-cookie-and-csrf-boundary']),
    dict(hub=0, path='web-tech/passkey-assertion-origin-and-signature-verification', title='Passkey Assertion, Origin, and Signature Verification', summary='Verify an assertion against a stored public key and a one-use sign-in challenge before creating a session.',
    definition='Passkey sign-in asks an authenticator to sign a fresh challenge with a private key scoped to a relying party. The server identifies the stored credential, verifies the signature and authenticator data, and creates a session only after every expected condition holds. A browser callback is merely a transport for the assertion; it is not proof of identity by itself. The server must compare the returned challenge, expected origin, relying-party ID, credential identifier, and applicable user verification policy. Credential counters and backup-state signals require cautious interpretation because synced authenticators can behave differently from a single hardware key.',
    case='Reviewer 29 starts sign-in and receives challenge S-62. A credential registered to the case-review origin returns an assertion. The server finds that credential under reviewer 29, checks that S-62 is current and unused, verifies origin and relying-party data, and uses the stored public key to verify the signature. Only then does it establish a new session. An assertion for reviewer 62’s account, a copied older S-47 response, or a response from a lookalike site must fail. The case detail endpoint still performs object authorization after sign-in.',
    implementation='Use a maintained WebAuthn verification library on the server rather than hand-assembling signature inputs. Store challenge purpose, expected account when known, expiry, and replay state in a server-controlled record. If a discoverable credential is used and the account was not selected first, map the verified credential ID to one account and enforce uniqueness; do not trust a browser-supplied username. Validate the signed authenticator data and client data, including user verification where the product requires it. Consume the challenge, rotate or create the session under normal fixation protections, and keep authorization separate from authentication.',
    cost='A verified assertion adds one public-key lookup, bounded cryptographic verification, and a session write. Indexing credential IDs makes lookup near O(1) in common stores, while keeping several credentials per account adds modest storage. Aggressive replay checks consume challenge state but prevent reuse of intercepted responses. Overly strict sign-counter assumptions can reject legitimate synced passkeys; record and investigate unusual counters under a policy rather than assuming every authenticator increments identically. Measure failed origin, challenge, signature, and user-verification checks without storing raw private assertions in routine logs.',
    failure='A server creates a session when the browser returns any credential ID, without checking its signed challenge. A copied response can be replayed. Another server verifies the signature but allows any origin in an overly broad list, weakening the site-binding property. Tighten expected origin and relying-party policy. Test wrong challenge, used challenge, wrong credential ID, altered signature, missing required user verification, and an account removed during the prompt. Confirm none creates a session. A valid sign-in must not grant access to a case assigned to another reviewer.',
    drill='Register two distinct credentials for reviewer 29 and one for reviewer 62. Sign in with a valid fresh challenge, then replay the assertion and mutate the origin or signature in controlled tests. Try a discoverable credential without a preselected username and verify the server maps it only after cryptographic validation. Remove reviewer 29 from organization 6 and confirm a valid authentication still fails the later case-authorization check. Capture only safe diagnostic categories in the logs.',
    decision='Create a session only after a fresh, scoped assertion verifies against the stored public key and current account policy.',
    code='function assertionRequestIsCurrent(request, response, now) {\n  return !request.used && now < request.expiresAt && request.challengeId === response.challengeId;\n}\nconsole.log(assertionRequestIsCurrent({ challengeId: "S-62", used: true, expiresAt: 80 }, { challengeId: "S-62" }, 47));\n// Output: false',
    checks=['Wrong or reused challenges cannot produce sessions.','Stored public key and exact expected origin drive verification.','Authentication never replaces case-level authorization.'], mistakes=['Treating a returned credential ID as proof of identity.','Skipping the server signature or origin check.','Assuming a valid login grants every object permission.'], related=['web-tech/object-level-authorization-for-reads-and-writes','web-tech/permission-revocation-and-active-sessions','web-tech/identity-and-application-security']),
    dict(hub=0, path='web-tech/passkey-conditional-sign-in-and-fallback', title='Passkey Conditional Sign-In and Fallback', summary='Offer passkeys without trapping users whose browser, authenticator, or credential is unavailable.',
    definition='A passkey sign-in interface must work when the credential is present and when it is not. A conditional browser prompt may suggest a discoverable credential in an input field, but support, platform behavior, and user settings differ. The application needs a clear direct sign-in action and an approved fallback such as another enrolled passkey, existing password flow, or recovery method. The fallback does not make a failed WebAuthn assertion valid; it starts a separate authenticated path. Avoid turning a canceled authenticator prompt into a permanent account lock or an endless spinner.',
    case='Reviewer 29 has a passkey on a phone but opens the case-review app on a shared workstation. The sign-in page offers Use a passkey and the organization’s approved alternative. If the browser shows no credential, the reviewer can choose another device or the separate recovery path. If a conditional prompt is dismissed, the username field and normal controls remain usable. Reviewer 62, who has never enrolled a passkey, should not see an error implying that the account is broken. The server applies the same rate and abuse controls to fallback paths.',
    implementation='Feature-detect WebAuthn before offering browser-dependent affordances, but do not equate API presence with a usable credential. Keep conditional mediation optional and cancel pending requests when the form mode changes or the route leaves, according to supported browser behavior. Give the person a visible path to choose a different method; avoid auto-retrying prompts after cancellation. The server owns method eligibility and account enumeration policy. When a password or recovery path succeeds, it issues a session under its own checks and may invite passkey enrollment after the session is established. Preserve focus and error text when switching methods.',
    cost='Conditional UI may reduce sign-in steps on familiar devices, but it adds states to test and can hold a pending browser request. A fallback increases maintenance cost yet prevents credential loss from becoming account loss. Requesting an unnecessary passkey prompt can interrupt work; hidden fallback links raise support burden. Measure successful sign-ins by method, cancellations, time to recover from a missing credential, and accessibility of method switching. Keep credential prompts distinct from server authentication outcomes in telemetry so a dismissed browser dialog is not counted as a security failure.',
    failure='The page calls a conditional passkey request and hides the password form until it resolves. On a workstation without the passkey, the prompt stays pending and the reviewer cannot sign in. Restore visible alternate actions and cancel or ignore the stale request when the mode changes. Another UI says No account found after a browser returns no credential, leaking account state without server evidence. Use neutral language and follow the existing enumeration policy. Test no API, no credential, canceled prompt, browser back, slow server challenge, and a second sign-in method succeeding while the first request remains pending.',
    drill='Try sign-in on a device with the passkey, another device without it, and a browser that lacks the chosen conditional flow. Leave the route during a pending prompt and return. Select the approved fallback with keyboard only, then finish sign-in and inspect focus, title, and session creation. Confirm the server never accepts a canceled or failed passkey response as evidence and that ordinary account-abuse controls still apply to alternate methods.',
    decision='Offer passkeys as a clear route to sign-in while retaining an independent, tested path for missing or unavailable credentials.',
    code='function availableSignInPaths(capability, hasApprovedFallback) {\n  return { passkey: capability === "available", fallback: hasApprovedFallback };\n}\nconsole.log(JSON.stringify(availableSignInPaths("missing", true)));\n// Output: {"passkey":false,"fallback":true}',
    checks=['No passkey or canceled prompt leaves another approved sign-in path.','Switching methods does not create a session from a failed assertion.','Keyboard and focus behavior remain usable across form modes.'], mistakes=['Hiding fallback until a browser prompt resolves.','Treating API availability as proof a credential exists.','Exposing account existence from a client-side no-credential result.'], related=['web-tech/account-recovery-and-session-revocation','web-tech/form-errors-and-recovery-paths','web-tech/route-scroll-and-focus-restoration']),
    dict(hub=0, path='web-tech/passkey-management-recovery-and-step-up', title='Passkey Management, Recovery, and Step-Up', summary='Let users remove lost credentials and require fresh assurance for sensitive account changes.',
    definition='Credential management is part of the authentication system. A user may enroll several passkeys, lose a device, replace a synced account, or suspect that an authenticator is no longer under their control. The product needs a way to inspect labeled credentials, add a new one, remove an old one, and recover access without letting recovery bypass all safeguards. Sensitive operations such as adding a credential, changing recovery channels, or exporting private data may require fresh proof of account control. That step-up decision should be server-owned, short-lived, and tied to the exact operation rather than a client-side flag.',
    case='Reviewer 29 loses a tablet that holds one of two passkeys. From a trusted session on a laptop, the reviewer opens credential settings, performs the product’s required fresh verification, removes the lost credential, and sees its last-used metadata. The server invalidates the credential for future assertions while leaving the second passkey usable. If both credentials are lost, the reviewer enters a distinct recovery workflow with delay or human review according to product risk. A recovery success should rotate active sessions where policy requires and should not automatically restore access to cases from an old tenant assignment.',
    implementation='Store credential IDs, public keys, creation time, last-used time, user-facing labels, and optional authenticator metadata under the account; do not store a private key. Require current authorization and recent verified assurance for add, remove, and recovery-channel changes. Define what happens when the user tries to remove the last usable credential. A recovery method needs its own abuse limits, audit record, and notification to existing channels, while avoiding account enumeration. After credential removal, reject future assertions for that ID even if a challenge was issued earlier. Reevaluate tenant and object permissions after recovery because authentication and authorization change independently.',
    cost='Credential lookup and removal are O(1) with an indexed identifier; each additional enrolled credential adds a small record and settings item. Step-up prompts add friction and may interrupt work, so restrict them to operations whose risk justifies it and record how long a proof remains valid. Recovery support is operationally expensive but prevents lockout. Too many recovery shortcuts can become the easiest attack path. Measure lost-device removal time, recovery completion and abuse, stale credential rejection, and whether users retain at least one working method after routine account changes.',
    failure='A reviewer removes a passkey in settings, but the credential remains accepted because a cache still marks it active. A later assertion signs in from the lost device. Invalidate the credential at the authoritative lookup and test immediately. Another flow lets a signed-in but unattended browser add a new passkey without fresh assurance. Require step-up. Finally, a recovery path that sends a link to an unverified new address lets an attacker take over the account. Treat recovery destination changes as sensitive operations with separate confirmation and logging.',
    drill='Enroll two credentials for reviewer 29. Remove one after step-up and attempt sign-in with it; it must fail while the other succeeds. Try removing the last credential and follow the documented recovery decision. Begin a sign-in before removal but finish it afterward, then inspect the server’s current credential check. Simulate loss of every credential and execute the recovery workflow under rate limits. After recovery, verify old sessions and case permissions follow current policy.',
    decision='Keep credentials manageable and recovery usable, while making account changes depend on fresh server-verified assurance.',
    code='function mayChangeCredentials(session, now) {\n  return session.assurance === "recent-verified" && now < session.assuranceExpiresAt;\n}\nconsole.log(mayChangeCredentials({ assurance: "signed-in", assuranceExpiresAt: 80 }, 47));\n// Output: false',
    checks=['Removed credential IDs fail subsequent assertions.','Sensitive credential changes require recent server-verified assurance.','Recovery does not revive stale tenant or object access.'], mistakes=['Treating a logged-in tab as sufficient proof for every credential change.','Leaving removed credentials active in a cache.','Making recovery easier to abuse than primary sign-in.'], related=['web-tech/account-recovery-and-session-revocation','web-tech/permission-revocation-and-active-sessions','web-tech/object-level-authorization-for-reads-and-writes']),
]

lessons.extend([
    dict(hub=1, path='web-tech/server-priced-order-snapshot-and-money-units', title='Server-Priced Order Snapshots and Money Units', summary='Build an immutable order total from trusted catalog data and currency-specific integer units.',
    definition='A checkout amount is an output of server-owned product, quantity, discount, tax, and delivery rules. A browser cart can propose items and quantities, but it cannot certify prices or final totals. Store monetary values in the currency’s defined minor unit where that unit exists, and keep currency attached to every amount. Some currencies have different decimal conventions, so a universal divide-by-one-hundred rule is wrong. Before starting payment, persist an order snapshot that records the accepted line prices, adjustments, currency, and version of the rules used. A later catalog update must not silently rewrite a pending order.',
    case='A field-equipment store receives a cart with three pressure sleeves at 4,700 minor units each and one inspection seal at 2,200. Delivery adds 900, yielding 17,200 minor units before any separately defined tax or discount. The client posts product IDs and quantities. The server looks up current prices, checks limits and stock, applies its own delivery and tax policies, creates order 47, and records the priced snapshot. If the browser changes a display total to 200, the payment session still uses 17,200. If stock changes before acceptance, the server reprices or rejects and asks for a new confirmation.',
    implementation='Validate product identity, quantity bounds, availability, address eligibility, applicable discounts, taxes, and shipping on the server. Make calculation rules explicit and record their version. Use integer minor units or an exact decimal representation appropriate to the currency; never use a binary floating-point sum as an accounting ledger. Check overflow and negative adjustments. Associate a stable order ID with a unique payment attempt and preserve the snapshot after provider handoff. Return the authoritative total for display and require an explicit confirmation when it differs from the cart preview. Treat inventory reservation and payment authorization as separate transitions with expiry and release rules.',
    cost='Pricing n lines is O(n) plus catalog and policy lookups. Batch fetching avoids n individual database calls, while reserving inventory adds contention around popular stock. Immutable snapshots increase storage by the number of line items but provide an audit trail when catalog prices change. Repricing on every browser refresh can cause contradictory totals; price at a named order transition and define when that quote expires. Measure cart-to-order mismatch, abandoned reprices, rounding corrections, and reservation expiry. A faster client total is useful for preview, but only the server total can be charged.',
    failure='The browser submits an amount beside its cart and the server forwards it to the payment provider. A modified request reduces a 17,200 order to 200. Recompute from trusted product IDs and rule versions. Another implementation stores 0.1-style floating values, then rounds only after discounts and tax, producing inconsistent totals across languages. Keep exact units and a documented rounding order. Test invalid quantities, missing catalog items, currency mismatch, expired discounts, concurrent stock changes, and a catalog price update after order creation. Reject an amount that cannot be represented safely.',
    drill='Create order 47 with the listed products and delivery charge. Compare the persisted snapshot, display total, and provider request in one test. Mutate the browser total and a line price; neither should change the server result. Reprice after a catalog update according to the quote-expiry rule, and confirm an accepted snapshot stays unchanged. Exercise a currency with different minor-unit rules, a zero-quantity line, an out-of-stock line, and an adjustment that would make the payable amount negative.',
    decision='Price on the server and persist one accepted, currency-aware snapshot before payment handoff.',
    code='function orderTotalMinor(lines, shippingMinor) {\n  return lines.reduce((total, line) => total + line.unitMinor * line.quantity, shippingMinor);\n}\nconsole.log(orderTotalMinor([{ unitMinor: 4700, quantity: 3 }, { unitMinor: 2200, quantity: 1 }], 900));\n// Output: 17200',
    checks=['Provider amount equals the accepted server snapshot.','Currency and rounding rules are explicit for each charge.','Changed browser fields cannot rewrite a priced order.'], mistakes=['Trusting a client-submitted total.','Applying one minor-unit convention to every currency.','Mutating an accepted order when catalog data changes.'], related=['web-tech/transactions-and-concurrent-writes','web-tech/idempotent-write-requests','web-tech/backend-api-systems']),
    dict(hub=1, path='web-tech/hosted-checkout-session-and-browser-return', title='Hosted Checkout Sessions and Browser Returns', summary='Bind a hosted payment attempt to a server order while treating the return page as a status view.',
    definition='A hosted checkout session lets a payment provider collect sensitive payment details outside the application’s form. The application server creates that session for a priced order and gives the browser a provider-approved redirect or token. A return to the success URL means the browser visited a URL; it does not prove a charge settled. Users can close the tab, arrive late, bookmark the route, or forge its query string. The order needs a server-owned pending state until a verified provider signal or status query confirms the relevant payment outcome.',
    case='Order 47 has a 17,200-unit snapshot. The server creates a provider session with order 47 as an internal reference, the correct currency and amount, an expiration, and an idempotency key for this attempt. Reviewer 29 is sent to the hosted page. The provider returns the browser to an order-status route before the webhook arrives. The page says Payment being confirmed and polls the application’s order status. It never marks the package ready solely because a success query parameter exists. If the user cancels, the order remains eligible for a new attempt under a defined expiry policy.',
    implementation='Create sessions from a server-authenticated order and validate that the caller owns or may act for it. Persist a payment-attempt record and use a stable idempotency key to prevent duplicate sessions on retries. Follow the provider’s current redirect or embedded-session contract, but keep card data out of application logs and forms when using hosted checkout. Include only nonsecret order references in return URLs. On return, fetch status from the application server, not the browser query string. Use server verification and provider events for state changes, and handle pending, failed, canceled, expired, authorized, captured, and disputed states according to the chosen payment model.',
    cost='Session creation is normally one provider call and one local write, but retries and slow responses need careful idempotency. Polling status every second for every open return tab creates needless load; use a bounded interval, backoff, or push channel where justified. A hosted flow reduces direct card-data handling but adds a redirect and an external dependency. Keep an order-status page usable when a provider is slow or unavailable. Measure duplicate attempts, pending duration, abandonment, session expiry, and mismatch between browser return and provider-confirmed state.',
    failure='The return route sees status=success in a query string and sets order 47 to paid. Anyone can open that URL without paying, so fulfillment begins incorrectly. Remove the client-side transition and show only server-confirmed state. Another flow creates a fresh provider session on every refresh, leaving several live attempts for one order. Use a stable attempt ID or an explicit retry transition with a new key. Test a forged return URL, browser close before return, provider timeout after session creation, canceled checkout, expired session, and two tabs starting checkout at once.',
    drill='Start payment for order 47 and record the local attempt ID, provider session ID, and idempotency key. Reload the start route twice; confirm a retry does not silently create extra payable attempts. Visit the return URL manually without payment and verify that status stays pending. Close the payment tab, let a verified event arrive, and check that the order-status page converges. Force provider timeout after a successful remote creation and reconcile before deciding whether another attempt is safe.',
    decision='Use the hosted session for payment collection and the return route for display, while the server owns payment truth.',
    code='function returnMessage(orderState) {\n  return orderState === "captured" ? "Payment confirmed" : "Payment being confirmed";\n}\nconsole.log(returnMessage("pending"));\n// Output: Payment being confirmed',
    checks=['A forged or early browser return cannot mark an order paid.','Retries do not create uncontrolled payment attempts.','The status page reflects server-confirmed state.'], mistakes=['Treating a success URL as payment evidence.','Placing secrets or card details in return URLs.','Creating a new payable session on every refresh.'], related=['web-tech/server-priced-order-snapshot-and-money-units','web-tech/idempotent-write-requests','web-tech/signed-webhook-delivery-and-replay']),
    dict(hub=1, path='web-tech/payment-webhook-reconciliation-and-idempotent-fulfillment', title='Payment Webhook Reconciliation and Idempotent Fulfillment', summary='Verify provider events and make order fulfillment safe under retries and out-of-order delivery.',
    definition='Payment providers send asynchronous status events, and delivery is usually retryable. A webhook is evidence only after its signature, account scope, event identity, and payload are validated under the provider’s contract. Even a verified event may be duplicated or arrive after a newer state. Fulfillment must therefore be an idempotent, server-owned transition tied to a confirmed payable amount and order. The browser return page can observe this transition but cannot trigger it by assertion. Where an event is ambiguous, fetch the provider’s current status before finalizing the order.',
    case='Order 47 is awaiting a 17,200-unit capture. The provider sends event E-62 twice, then retries E-47 from an earlier authorization state. The handler verifies each raw event, records unique event IDs, checks the provider payment ID and amount against order 47, and advances from pending to captured once. A unique fulfillment key allows one warehouse release. The duplicate E-62 is acknowledged without a second shipment; older E-47 cannot move the order backward. If the webhook never arrives, a scheduled reconciliation query finds the provider’s captured state and applies the same transition.',
    implementation='Preserve the raw request bytes required by the provider’s signature scheme and verify before parsing or trusting fields. Check event ID, provider account, payment object, currency, amount, and relation to the local order. Store processed event IDs under a uniqueness constraint and perform state transition plus fulfillment-outbox insertion in one transaction. A worker consumes the outbox with its own idempotency key. Acknowledge duplicates deliberately, retry transient internal failures, and quarantine mismatches for review. Use a reconciliation job for missing or delayed events; do not assume webhook order reflects payment-state order.',
    cost='Signature verification is bounded cryptographic work. Indexed event and payment lookups are near O(1), while every event adds a small deduplication record and audit trail. An outbox adds a write and worker hop but prevents a crash between paid-state update and shipment request from losing work. Reconciliation costs provider reads and must respect rate limits; sweep unresolved attempts with backoff rather than querying every historical payment. Track capture-to-fulfillment delay, duplicate events, mismatched amounts, unresolved attempts, and repeated outbox delivery. Acknowledging too early can lose a transition; acknowledging too late can flood retries.',
    failure='A handler updates the order to paid, then crashes before shipping. The provider retries, but the handler sees paid and exits, leaving an unfulfilled order. Write the state change and outbox item atomically, then retry the worker. Another handler fulfills immediately from a browser success callback and ships twice when the webhook arrives. Keep one authoritative transition and unique fulfillment key. Test duplicate events, reversed event order, bad signature, wrong account, wrong amount, missing webhook, provider query disagreement, database failure before commit, and worker crash after an external shipment call.',
    drill='Send a signed capture event for order 47, then replay it five times and reorder it with an older authorization event. Confirm one paid transition and one fulfillment intent. Send a validly signed event for a different amount and verify quarantine. Stop the webhook worker, let provider status become captured, and run reconciliation. Crash the fulfillment worker after its external request, retry it, and confirm the warehouse receives one effective instruction by key.',
    decision='Verify provider evidence and use one idempotent state transition for both webhook and reconciliation paths.',
    code='function fulfillmentKey(orderId, paymentId) {\n  return `fulfill:${orderId}:${paymentId}`;\n}\nconsole.log(fulfillmentKey(47, "pay-62"));\n// Output: fulfill:47:pay-62',
    checks=['Duplicate and out-of-order events cannot duplicate fulfillment.','Amount, currency, account, and signature are checked before mutation.','Missing events can be reconciled through the same transition.'], mistakes=['Parsing before a raw-body signature check required by the provider.','Assuming delivery order is payment-state order.','Updating paid status separately from fulfillment intent.'], related=['web-tech/signed-webhook-delivery-and-replay','web-tech/transactions-and-concurrent-writes','web-tech/idempotent-write-requests']),
    dict(hub=1, path='web-tech/refunds-reversals-and-payment-ledger-state', title='Refunds, Reversals, and Payment Ledger State', summary='Track partial refunds and disputes as separate money movements with bounded, reconcilable state.',
    definition='A payment is not a single Boolean. Authorization, capture, refund, failed refund, chargeback, and reversal are distinct money movements with different timing. A fulfilled order can later have a refund; an authorized payment can expire before capture; a dispute can change recoverable funds without erasing the original capture. Model these changes as append-only ledger entries or equivalently auditable state transitions, and keep order fulfillment state separate from payment balance. Refund eligibility is bounded by captured money less completed refunds and other provider-specific constraints, using exact currency units.',
    case='Order 47 captured 17,200 minor units and shipped. A damaged pressure sleeve prompts a 4,700-unit partial refund request. A support actor with refund permission records the reason, checks the remaining refundable balance, and sends one provider request with an idempotency key. The provider accepts the request but final settlement is pending; the user sees that state. When a verified refund event confirms completion, the ledger records 4,700 refunded and 12,500 still captured after refund. A second identical support click cannot create another 4,700 refund. A later dispute is recorded separately, not disguised as a refund.',
    implementation='Authorize who may request a refund and require a reason or approval according to business policy. Calculate maximum refundable from authoritative captures and completed or reserved refund amounts, taking in-flight requests into account to avoid over-refunding across concurrent workers. Use an idempotency key and persist request, provider object ID, and outcome. Confirm asynchronous completion through signed provider events or reconciliation, with failed attempts leaving accurate available balance. Keep currency consistent and record entries with timestamps, actor, order ID, payment ID, and provider reference. Never delete capture history when a refund succeeds.',
    cost='With indexed ledger entries, a balance may be computed in O(k) for k movements on the payment or maintained as a transactional summary for frequent reads. A summary is faster but must reconcile to immutable entries. Concurrent partial refunds need a lock or compare-and-swap on the remaining amount. Provider calls and disputes can remain unresolved for hours or longer, so expose pending state without pretending it has settled. Monitor over-refund rejection, pending age, ledger-to-provider differences, and support retries. Extra audit storage is a deliberate cost of money correctness.',
    failure='Two support agents each see 17,200 refundable and both request 12,500 at the same time. A naive read-then-write path sends 25,000 in requests against one capture. Reserve refundable balance in one transaction and use provider idempotency. Another UI marks refunded as soon as a request is accepted, even when the provider later fails it. Separate requested, pending, completed, and failed states. Test concurrent partial refunds, duplicated clicks, a failure after provider acceptance, wrong currency, dispute after refund, and reconciliation when a final event is absent.',
    drill='Capture 17,200 units for order 47, request a 4,700-unit refund, and inspect the pending balance and event history. Confirm the completed balance is 12,500. Repeat the request with the same key and verify no second money movement. Attempt two concurrent refunds whose sum exceeds the remaining balance, then inject a failed refund event and restore only the correctly reserved amount. Add a dispute record and verify order shipping history remains intact.',
    decision='Represent money movements and fulfillment independently, with exact units and idempotent transitions for every reversal.',
    code='function refundableMinor(capturedMinor, completedRefundMinor) {\n  return Math.max(0, capturedMinor - completedRefundMinor);\n}\nconsole.log(refundableMinor(17200, 4700));\n// Output: 12500',
    checks=['Concurrent refunds cannot exceed the captured amount.','Pending and failed refunds are not labeled completed.','Reversals preserve capture and fulfillment history.'], mistakes=['Using a paid flag as the entire ledger.','Deleting a capture when a refund settles.','Ignoring in-flight refunds during balance checks.'], related=['web-tech/payment-webhook-reconciliation-and-idempotent-fulfillment','web-tech/transactions-and-concurrent-writes','web-tech/signed-webhook-delivery-and-replay']),
])

